mapper.update:
update policy
name = #{name}, subject_type = #{subjectType}, subject_id = #{subjectId}, resource = #{resource}, action = #{action}, effect = #{effect}, condition_expr = #{conditionExpr}, priority = #{priority}, status = #{status}, remark = #{remark}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select id, name, subject_type, subject_id, resource, action, effect,
condition_expr, priority, status, remark, create_time, update_time
from policy


        name like concat('%',#{name},'%')


        and subject_type = #{subjectType}


        and resource = #{resource}


        and action = #{action}


        and effect = #{effect}


        and status = #{status}


        and create_time between #{begin} and #{end}


order by priority desc, id asc

mapper.delete:
delete from policy
where id in

    #{id}

mapper.select:
select id, name, subject_type, subject_id, resource, action, effect, condition_expr, priority, status, remark, create_time, update_time from policy where status = 1 and (resource = #{resource} or resource = '*') and (action = #{action} or action = '*') and (
(subject_type = 1 and subject_id in
#{roleId}
) or
(subject_type = 2 and subject_id = #{empId}) ) order by priority desc, id asc
